<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientIdTokenEncryptedResponseEncAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientIdTokenEncryptedResponseEncAccessor trait.
 *
 * Covers null default, string/VO assignment via withIdTokenEncryptedResponseEnc,
 * getIdTokenEncryptedResponseEnc/idTokenEncryptedResponseEnc accessors, and isIdTokenEncryptedResponseEncChanged with/without original.
 */
class TrustedClientIdTokenEncryptedResponseEncAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withIdTokenEncryptedResponseEnc creates a new instance with the IdTokenEncryptedResponseEnc set
     * from a string value, and getIdTokenEncryptedResponseEnc returns the primitive string.
     */
    public function testWithIdTokenEncryptedResponseEncFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenEncryptedResponseEncAccessorUnitTest();

        // Act
        $result = $holder->withIdTokenEncryptedResponseEnc('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getIdTokenEncryptedResponseEnc());
    }
    /**
     * Asserts that withidTokenEncryptedResponseEnc has access to the value object
     * from a string value, and getIdTokenEncryptedResponseEnc returns the primitive string.
     */
    public function testWithIdTokenEncryptedResponseEncFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenEncryptedResponseEncAccessorUnitTest();

        // Act
        $result = $holder->withIdTokenEncryptedResponseEnc('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->idTokenEncryptedResponseEnc()->value());
    }
    public function testChangedIdTokenEncryptedResponseEnc(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenEncryptedResponseEncAccessorUnitTest();
        $original = $holder->withIdTokenEncryptedResponseEnc('one');
        $same = $holder->withIdTokenEncryptedResponseEnc('one');
        $modified = $holder->withIdTokenEncryptedResponseEnc('other');

        // Act
        $unchanged = $holder->isIdTokenEncryptedResponseEncChanged();
        $withSame = $original->isIdTokenEncryptedResponseEncChanged($same);
        $withDiferent = $original->isIdTokenEncryptedResponseEncChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientIdTokenEncryptedResponseEncAccessorUnitTest
{
    use TrustedClientIdTokenEncryptedResponseEncAccessor;
}
